"use client"

import { useState, useEffect } from "react"
import Image from "next/image"
import Link from "next/link"
import { siteConfig } from "@/config/site-config"
import { useI18n } from "@/lib/i18n-context"

export function SolutionsSection() {
  const solutions = siteConfig.solutions || []
  const [hoveredBtn, setHoveredBtn] = useState<number | null>(null)
  const [isMobile, setIsMobile] = useState(false)
  const { t } = useI18n()

  // 检测是否为移动端
  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 768)
    }
    window.addEventListener('resize', handleResize)
    handleResize() // 设置初始值
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  return (
    <section 
      className="pt-0 pb-10 md:py-20"
      style={{ backgroundColor: '#f9f9f9', marginTop: 0, paddingTop: 0 }}
    >
      <div className="container mx-auto px-5">
        <h2 className="text-center mb-15 relative text-[#333333] text-[32px] font-semibold">
          {t('nav.solutions')}
        </h2>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {solutions.map((solution) => {
            // 根据屏幕大小选择合适的图片
            const imageUrl = isMobile && solution.imageMobile ? solution.imageMobile : solution.image
            
            return (
              <div 
                key={solution.id}
                className="relative rounded-lg overflow-hidden h-[360px] cursor-pointer w-full m-0 transition-all duration-300 hover:-translate-y-[5px] hover:shadow-[0_8px_24px_rgba(0,0,0,0.2)]"
              >
                <div className="w-full h-full">
                  <Image
                    src={imageUrl}
                    alt={solution.title}
                    fill
                    className="object-cover"
                    style={{ transform: 'scale(1.05)' }}
                  />
                </div>
              <div 
                className="absolute top-0 left-0 w-full h-full flex flex-col justify-center items-center text-center p-5 text-white"
                style={{
                  backgroundColor: 'rgba(30, 110, 198, 0.7)'
                }}
              >
                <h3 className="text-2xl mb-4">
                  {solution.id === 1 && t('solutions.smartHospital')}
                  {solution.id === 2 && t('solutions.smartHealthcare')}
                  {solution.id === 3 && t('solutions.smartCommunity')}
                  {solution.id === 4 && t('solutions.smartBuilding')}
                </h3>
                <p className="text-[15px] leading-relaxed mb-5">
                  {solution.id === 1 && t('solutions.smartHospitalDesc')}
                  {solution.id === 2 && t('solutions.smartHealthcareDesc')}
                  {solution.id === 3 && t('solutions.smartCommunityDesc')}
                  {solution.id === 4 && t('solutions.smartBuildingDesc')}
                </p>
                <Link
                  href={solution.href}
                  className="inline-block px-5 py-2.5 text-white no-underline rounded transition-all duration-300 font-medium border-none cursor-pointer text-center"
                  style={{
                    backgroundColor: hoveredBtn === solution.id ? '#004d99' : '#0066cc',
                    transform: hoveredBtn === solution.id ? 'translateY(-2px)' : 'translateY(0)'
                  }}
                  onMouseEnter={() => setHoveredBtn(solution.id)}
                  onMouseLeave={() => setHoveredBtn(null)}
                >
                  {t('common.learnMore')}
                </Link>
              </div>
            </div>
          )})}
        </div>
      </div>
    </section>
  )
}
